schema:
CREATE TABLE IF NOT EXISTS clients(id TEXT PRIMARY KEY,name TEXT NOT NULL CHECK(length(trim(name)) BETWEEN 1 AND 120),phone TEXT NOT NULL CHECK(length(trim(phone)) BETWEEN 1 AND 32));
CREATE TABLE IF NOT EXISTS sales(id TEXT PRIMARY KEY, date TEXT NOT NULL,warehouse TEXT NOT NULL REFERENCES warehouses(id),account TEXT NOT NULL REFERENCES accounts(id),client TEXT REFERENCES clients(id),warehouseName TEXT NOT NULL,accountName TEXT NOT NULL,clientName TEXT, seller TEXT NOT NULL CHECK(length(trim(seller)) BETWEEN 1 AND 100),role TEXT NOT NULL CHECK(length(trim(role)) BETWEEN 1 AND 80), discount INTEGER NOT NULL CHECK(typeof(discount)='integer' AND discount>=0), tender INTEGER NOT NULL CHECK(typeof(tender)='integer' AND tender>=0), total INTEGER NOT NULL CHECK(total>=0), paid INTEGER NOT NULL CHECK(paid>=0 AND paid<=total), CHECK(client IS NOT NULL OR paid=total));
CREATE TABLE IF NOT EXISTS sale_lines(sale TEXT NOT NULL REFERENCES sales(id),lot TEXT NOT NULL,name TEXT NOT NULL,unit TEXT NOT NULL,qty REAL NOT NULL CHECK(qty>0),baseQty REAL NOT NULL CHECK(baseQty>0),price REAL NOT NULL CHECK(price>=0),listPrice REAL NOT NULL CHECK(listPrice>=0),amount INTEGER NOT NULL CHECK(amount>=0));
CREATE INDEX IF NOT EXISTS sale_lines_lot ON sale_lines(lot);
CREATE TABLE IF NOT EXISTS stock_movements(
id TEXT PRIMARY KEY,lot TEXT NOT NULL, source TEXT NOT NULL REFERENCES warehouses(id),target TEXT REFERENCES warehouses(id),qty REAL NOT NULL CHECK(qty!=0),name TEXT NOT NULL,price REAL NOT NULL,created INTEGER NOT NULL, CHECK(target IS NULL OR (target!=source AND qty>0)));
DROP VIEW IF EXISTS sale_stock;
CREATE VIEW sale_stock AS
WITH receipts AS (SELECT id,posted_at,quantity,warehouse_id,product_id,product_name,unit,content_unit,quantity_per_piece,sale_price,json_array(warehouse_id,product_id,unit,content_unit,quantity_per_piece) AS lot FROM stock_receipts WHERE status='posted'
UNION ALL SELECT id,created,CASE WHEN target IS NULL THEN qty ELSE -qty END,source,json_extract(lot,'$[1]'),name,json_extract(lot,'$[2]'),json_extract(lot,'$[3]'),json_extract(lot,'$[4]'),price,lot FROM stock_movements
UNION ALL SELECT id,created,qty,target,json_extract(lot,'$[1]'),name,json_extract(lot,'$[2]'),json_extract(lot,'$[3]'),json_extract(lot,'$[4]'),price,json_set(lot,'$[0]',target) FROM stock_movements WHERE target IS NOT NULL),
groups_ AS (SELECT lot,sum(quantity) AS received FROM receipts GROUP BY lot)
SELECT r.lot AS id,r.product_id AS productId,r.warehouse_id AS warehouse,r.product_name AS name,r.unit,r.content_unit AS contentUnit,coalesce(r.quantity_per_piece,1) AS factor,coalesce(r.sale_price,0)*coalesce(r.quantity_per_piece,1) AS price,
round(g.received-coalesce((SELECT sum(l.baseQty) FROM sale_lines l WHERE l.lot=r.lot),0),9) AS stock
FROM groups_ g JOIN receipts r ON r.lot=g.lot AND r.id=(SELECT x.id FROM receipts x WHERE x.lot=g.lot ORDER BY x.posted_at DESC,x.id DESC LIMIT 1);
